// Complete reports are a core delivery mode; this static prototype does not fabricate a live run.
const v4ReportSections=[
 ['01','研究范围与事件背景','主题、时间窗、平台覆盖、关键词、去重规则、事件时间线。','一手原文、日期与研究范围'],
 ['02','舆情总览与情感分布','去重样本量、正/中/负标签、缺失与未分类，完整统计表及图。','逐条采集记录、标签模型、样本口径'],
 ['03','传播平台与时间趋势','平台分布、真实时间桶趋势、关键节点对照；热度指数与发帖量分开。','平台字段、发布时间、窗口覆盖'],
 ['04','传播主体、地域与讨论焦点','主体类别、可得的公开属地、主题聚类与代表性原话。','原生可得字段；缺失单列，不反推 IP'],
 ['05','专题机制、背景与案例','行业背景、机制或产业链、对比案例、来源分歧和反证。','新闻、公开研究、一手通报与独立证据'],
 ['06','影响、建议与证据附录','限定范围的判断、适用条件、可执行建议、争议、缺口和引用。','结论—片段—原文快照关联与数据表附件']
];
const v4Preserve=[['InsightEngine','查库、关键词优化、情感分析、聚类抽样与反思'],['MediaEngine','多模态/网页检索、信息卡、首轮总结与反思'],['QueryEngine','新闻检索、时间窗、首轮总结与反思'],['ForumEngine','多成员论坛、主持引导与研究反馈循环'],['ReportEngine','六模板、切片、布局、篇幅、逐章写作与装订'],['IR / 图表 / 导出','表格、Chart/词云、数值校验、JSON 修复、HTML/MD/PDF']];
v4State.deepSpec=null;
function v4DeepView(){const spec=v4State.deepSpec;document.getElementById('p-deepreport').innerHTML=`<div class="topbar"><h1>📑 深度研判 · 完整报告</h1><span class="sub">完整保留 BettaFish 研究与成稿能力</span><button class="btn dark" style="margin-left:auto" onclick="v4DeepRequest()">＋ 发起深度研判</button></div><div class="v4-deep-hero"><div><span class="v4-source-tag">完整交付模式</span><h2>不是一段总结，而是一份有数据、图表与证据的报告。</h2><p>三引擎与论坛研究 → 领域审查 → 六套模板 → 逐章成稿 → 图表 / 表格质检 → HTML / MD / PDF。</p><div class="v4-report-actions"><button class="btn dark" onclick="v4DeepRequest()">深度研判一个主题</button><a class="btn" href="report-benchmark.html" target="_blank" rel="noopener">查看用户提供的 15 页样稿 ↗</a><button class="btn v4-ask-btn" onclick="v4AskReport('ai')">💬 追问报告</button></div></div><a href="report-benchmark.html" target="_blank" rel="noopener" aria-label="打开用户参考报告"><img src="reference-pages/page-01.png" alt="用户提供的报告封面缩略图"></a></div>${spec?`<div class="v4-panel"><div class="v4-between"><h3>研究草案：${v4Esc(spec.topic)}</h3>${v4Tag('待接入真实数据','o')}</div><p class="v4-label">${v4Esc(spec.window)} · ${v4Esc(spec.template)} · 真实采样与来源核验优先</p><div class="v4-note orange">当前仅建立了本地研究草案，没有发起真实模型、检索或采集。完整报告需要实际原文与数据表；不会生成虚构数量和曲线填充章节。</div></div>`:''}<div class="v4-panel"><div class="v4-between"><h3>📚 完整报告章节合同</h3><span class="v4-label">保持完整结构，按证据决定内容与篇幅</span></div><div class="v4-scroll-table"><table><thead><tr><th>章节</th><th>内容与交付形式</th><th>真实数据前提</th></tr></thead><tbody>${v4ReportSections.map(([n,t,d,r])=>`<tr><td><b style="color:#7c5cf0">${n} · ${t}</b></td><td>${d}</td><td class="v4-label">${r}</td></tr>`).join('')}</tbody></table></div></div><div class="v4-row"><div class="v4-panel"><h3>📊 数据表和图表必须有底表</h3><div class="v4-note green">原始采集 / 授权导入 → 去重与过滤 → 代码统计 → 数据表 → 图表 → 文字解释。</div><p class="v4-label">每项统计保存查询或代码版本、分子分母、时间窗、平台范围和样本数。数字可以从附表复算；情感比例注明标签模型和抽样方式。</p><button class="btn" onclick="v4DataContract()">查看统计与图表清单</button></div><div class="v4-panel"><h3>🔎 真实观测与估算分开</h3><p class="v4-label">本地观测、外部原文引用、可复算派生值与估算分别标记。真实数据报告默认不使用从总量反推的日趋势，不通过模型推断不存在的地域字段。</p><div class="v4-note orange">样稿第 6 页说明日数据是“基于总信息量的趋势估算”。这里只参考其结构与版式，不把样稿所有数字视为已经核实。</div></div></div><div class="v4-panel"><h3>🧩 BettaFish 功能保留清单</h3><div class="v4-key-grid">${v4Preserve.map(([t,d],i)=>`<div class="v4-key-card" style="--v4-color:${v4Colors[i%8]}"><h4>${t}</h4><p class="v4-label">${d}</p>${v4Tag('核心验收 · 不删除','p')}</div>`).join('')}</div><div class="v4-note">当前保留的是界面入口和明确的接入要求；后端尚未完成迁移，不能把这些卡片视作已运行成功。实施以原引擎实际能力的回归结果验收。</div></div>`;}
function v4DeepRequest(){const latest=v4Session().messages.filter(m=>m.role==='user').at(-1)?.text||'';v4Modal('深度研判 / 完整图文报告',`<form id="v4-deep-form"><div class="v4-field"><label for="v4-deep-topic">研究主题</label><textarea name="topic" id="v4-deep-topic" required placeholder="例如：深度研判近期 AI 行业舆情，分析事实、平台讨论、分歧与风险。">${v4Esc(/深度|报告|研究/.test(latest)?latest:'')}</textarea></div><div class="v4-row"><div class="v4-field"><label>研究窗口</label><select name="window"><option>近 7 天</option><option>近 24 小时</option><option>近 30 天</option><option>按事件自定义</option></select></div><div class="v4-field"><label>报告模板</label><select name="template">${['社会公共热点事件分析报告','企业品牌声誉分析报告','日常或定期舆情监测报告','市场竞争格局舆情分析报告','政策或行业动态舆情分析报告','突发事件与危机公关报告'].map(t=>`<option>${t}</option>`).join('')}</select></div></div><div class="v4-note green">交付：完整章节 + 原始口径 + 统计附表 + 图表 + 来源附录 + HTML / Markdown / PDF。</div><div class="v4-field"><label>数据策略</label><select name="policy"><option>真实观测与原文引用；缺失不补造</option><option>允许额外展示估算，但必须与真实观测明确分栏</option></select></div><div class="v4-note">保留三引擎、多轮反思、Forum 主持、ReportEngine 完整成稿管线。此处仅建立原型草案；实际运行需要接通采集库、检索、模型与导出服务。</div><button class="btn dark" type="submit">建立深度研究草案</button></form>`);}
function v4DataContract(){v4Modal('统计底表与图表验收',`<table><thead><tr><th>图 / 表</th><th>计算来源</th></tr></thead><tbody>${[['信息总量 / 去重明细','逐条内容记录与内容 ID / URL 去重'],['每日或小时趋势','真实发布时间与完整时间桶，缺失标记'],['平台与主体分布','真实平台 / 主体类别；未知单列'],['情感分布','样本与标签、模型版本、抽样和复核'],['地域 TOP','仅使用合法取得的原生公开属地字段'],['关键词 / 讨论焦点','有效文本、聚类 / 标签和代表性片段'],['时间线 / 案例对照','可回溯一手原文与发布时间'],['来源与证据附录','结论—证据—原文定位、查询与代码版本']].map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`).join('')}</tbody></table><div class="v4-note orange">热榜有排名不等于有帖子总量；有帖子不等于有 IP 属地。缺字段的维度标为未覆盖，而不是交给模型补齐。</div>`);}
const v4PlainAnswer=v4Answer;
v4Answer=function(q){if(/深度|完整报告|详细报告|生成报告|出报告/.test(q))return {text:'可以把这个需求设为“深度研判 / 完整报告”。交付目标包括：\n1. 事件背景与时间线；\n2. 样本总览、情感与平台分布；\n3. 真实观测的传播趋势与统计表；\n4. 讨论焦点、来源分歧与专题机制；\n5. 结论、建议、证据缺口和来源附录。\n\n三引擎、Forum 多轮研究与 ReportEngine 的六模板、逐章生成、IR、图表/表格校验及 PDF 导出都保留。当前原型不能生成新的真实数据，点击下方建立研究草案。',deep:true};return v4PlainAnswer(q);};
const v4PlainMessageHTML=v4MessageHTML;
v4MessageHTML=function(m){return v4PlainMessageHTML(m)+(m.deep?'<div class="v4-report-actions" style="margin:0 0 15px 35px"><button class="btn dark" onclick="v4DeepRequest()">📑 发起深度研判 / 完整报告</button></div>':'');};
const v4PlainRenderChat=v4RenderChat;
v4RenderChat=function(){v4PlainRenderChat();document.querySelector('#p-chat .topbar').insertAdjacentHTML('beforeend','<button class="btn dark" onclick="v4DeepRequest()">📑 深度研判 / 完整报告</button>');};
document.addEventListener('submit',e=>{if(e.target.id!=='v4-deep-form')return;e.preventDefault();const d=new FormData(e.target);v4State.deepSpec={topic:String(d.get('topic')).trim(),window:String(d.get('window')),template:String(d.get('template')),policy:String(d.get('policy'))};v4CloseModal();v4DeepView();v4Go('deepreport');showToast('完整研究草案已建立；真实执行等待后端接入');});
v4DeepView();v4RenderChat();
document.querySelector('#p-report .v4-rich-hero').insertAdjacentHTML('afterend','<div class="v4-rich-hero" style="background:#f8f1f4;border-color:#ecd9e1"><span class="v4-icon">📑</span><div style="flex:1"><h3 style="color:#8b294c">深度报告交付标准 · 用户 15 页样稿</h3><p>完整研究、统计表、图表、专题分析与可回溯来源。</p></div><button class="btn" onclick="v4Go(\'deepreport\')">查看完整报告标准</button><button class="btn dark" onclick="v4DeepRequest()">发起深度研判</button></div>');
